PAYLOAD=''
import base64,zipfile,io,os,sys,shutil
from pathlib import Path
import torch
zipfile.ZipFile(io.BytesIO(base64.b64decode(PAYLOAD))).extractall('/kaggle/working')
os.chdir('/kaggle/working');sys.path.insert(0,os.getcwd())
from faceforge.data import manifest
from faceforge.train import train
print('CUDA',torch.cuda.is_available(),torch.cuda.get_device_name(0),flush=True)
files=sorted(p for p in Path('/kaggle/input').rglob('*.jpg'))[:10000]
if len(files)<10000: raise RuntimeError(f'Only {len(files)} face images')
os.makedirs('selected',exist_ok=True)
for i,p in enumerate(files):os.symlink(str(p),f'selected/{i:06}.jpg')
prior=list(Path('/kaggle/input').rglob('checkpoint.pt'))
print('prior checkpoints',len(prior),flush=True)
if len(prior)!=1: raise RuntimeError('Expected exactly one recovery checkpoint')
run=Path('run');run.mkdir(exist_ok=True)
old=prior[0].parent
shutil.copy2(old.parent/'manifest.json','manifest.json')
import json,hashlib
a=json.loads(Path('manifest.json').read_text())
assert len(a['rows'])==10000 and a['root']=='/kaggle/working/selected'
for r in a['rows'][:32]: assert hashlib.sha256((Path('selected')/r['path']).read_bytes()).hexdigest()==r['sha256']
print('manifest_sha256',hashlib.sha256(Path('manifest.json').read_bytes()).hexdigest(),flush=True)
if (old/'metrics.jsonl').exists(): shutil.copy2(old/'metrics.jsonl',run/'metrics.jsonl')
for p in old.glob('fixed_epoch_*.png'): shutil.copy2(p,run/p.name)
train('manifest.json','run',epochs=30,batch=128,z_dim=128,width=64,device='cuda',lr=.0002,d_lr=.0002,resume=str(prior[0]))
print('FINISHED',flush=True)
